# 문항 후보의 칸별 관측 수 사전 확인(집계만)
from common import *
df, cb = load()
H = df[df['head'] == 1]
def n(cond, d=df): return int(d.eval(cond, engine='python').sum())
def tab(cond, by, d=df):
    s = d[d.eval(cond, engine='python')]
    return s.groupby(by).size().to_dict()
print('A002 highbp 65+:', n('age >= 65 and nhi_highbp_yn == 1'), 'pop', n('age >= 65'))
print('A003 childcare yn1 by age<3:', tab('childcare_yn1 == 1', df.age >= 3), 'yn2:', tab('childcare_yn2 == 1', df.age >= 3))
print('A006 kua type x sex:', tab('kua_yn1 == 1', ['kua_type', 'gender']))
print('A007 disp_bn age:', tab('disp_bn_yn1 == 1', pd.cut(df.age, [-1, 17, 64, 200])))
print('A008 visit by grade:', tab('ltcare_visit_yn == 1', 'ltcare_grade'))
print('A011 self:', n('self_yn1 == 1'), n('self_yn1 == 1 and self_yn2 == 1'))
print('A012 tehosp in by sido:', tab('sido in [2, 7, 16] and nhi_in_tehospital_dur > 0', 'sido'))
print('A013 aftsch 6-17 by inc5:', tab('age >= 6 and age <= 17 and pubedu_aftsch_yn == 1', 'inc5'), 'pop', tab('age >= 6 and age <= 17', 'inc5'))
